"""Course questions, shared case orientation, resources, and final decision."""
from retail_case import SPEC
from retail_content import MAP
from retail_ui import p,esc,table,shell,formula

def document(title,lead,sections):
    return '<main id="main"><div class="hero wrap"><p class="eyebrow">The retail decision · Data to decisions</p><h1>'+esc(title)+'</h1><p class="lead">'+esc(lead)+'</p></div><div class="content wrap">'+''.join(f'<section id="{key}"><h2>{esc(heading)}</h2>{body}</section>' for key,heading,body in sections)+'</div></main>'

def publish_pages(write,r):
    f=lambda x:f'{x:.2f}'
    questions=[('What is happening, and where?','Measure the problem, compare stores, and judge the precision of an audit.','lesson-1.html'),
        ('What can we predict before acting?','Explain store differences and test a forecast on later weeks.','lesson-4.html'),
        ('What would change if we acted?','Evaluate alerts through a pilot, voluntary adoption, and a later rollout.','lesson-7.html'),
        ('Which action is worth its cost?','Combine the evidence into a staged expansion recommendation.','synthesis.html')]
    cards=''.join(f'<a class="card" href="{url}"><p class="eyebrow">Question {i}</p><h3>{esc(q)}</h3>{p(d)}</a>' for i,(q,d,url) in enumerate(questions,1))
    lessons=''.join(f'<a class="card" href="lesson-{i}.html"><p class="eyebrow">Lesson {i:02d} · {esc(stage)}</p><h3>{esc(title)}</h3><p>{esc(method)}</p><span class="meta">Follow the case →</span></a>' for i,(title,method,stage) in enumerate(MAP,1))
    home='<main id="main"><div class="hero wrap"><p class="eyebrow">One running case · Ten connected lessons</p><h1>How should a retail chain reduce stockouts profitably?</h1><p class="lead">Empty shelves disappoint customers. Extra inventory ties up cash. Follow the same stores as the company measures the problem, forecasts which stores need attention, tests replenishment alerts, and decides where to expand.</p><div class="downloads"><a class="button" href="lesson-1.html">Begin the first decision</a><a href="study-guide.html">Meet the case and its data →</a></div></div><div class="wrap">'
    home+='<section id="big-questions" class="section-head"><h2>Four questions organize the course.</h2><div class="cards">'+cards+'</div></section>'
    home+='<section id="learning-map" class="section-head"><h2>Read it, present it, and work through it.</h2>'+p('Each lesson begins with a decision brief. Follow the same data through worked analyses, then add an entry to the management memo. Choose Present lesson for a classroom view of the same teaching blocks; open Notes for their explanations. Technical continuations use the same variables and calculations.')+'<div class="cards">'+lessons+'</div></section>'
    home+='<section id="teaching-data" class="notice"><strong>About the case data.</strong> The stores, records, and outcomes are fictional and generated from one documented model with a fixed seed. They support practice in making business decisions; they are not evidence about an actual retail chain. Known answers are revealed after the decision exercises. The generator and full model are available in the technical continuations and labs.</section>'
    home+='<p style="margin:30px 0">No account is required. Answers are discussed on the page and are not submitted or stored.</p></div></main>'
    write('index.html',shell('One retail decision. Four big questions.',home,'index.html'))
    timeline=table(['Release','When','Who and why'],[
        ['Operating baseline','Weeks 1–16','All 150 stores; repaired weeks 1–8 form store profiles'],
        ['Independent shelf audit','Week 16','30 randomly sampled stores; a new measurement of current availability'],
        ['Forecast exercise','Target weeks 3–16','Train 3–10, validate 11–13, evaluate 14–16'],
        ['Randomized pilot','Weeks 17–24','S001–S050; 25 random offers, 25 usual-operation stores'],
        ['Voluntary adoption','Starts week 17; assess 17–24','S051–S100; adoption follows starting conditions'],
        ['Later rollout','Starts week 25; assess 25–32','S101–S150; 25 selected adopters and 25 comparisons']],'The business history behind the lessons')
    case=document('Meet the decision before the methods.','You are advising a retail operations director on whether, where, and how to expand replenishment alerts.',[
        ('business','The action the company is considering',p('Each week, an alert identifies low-stock products for a store team to review before replenishment. The team can bring forward orders where appropriate. Management wants a reliable service improvement that covers the extra service and inventory cost.','Your role is to keep that decision visible as the evidence changes. At first, the data establish the scale of the problem. Later, they support forecasts and evaluate the policy through different study designs.')),
        ('measurement','One outcome and one accounting rule',p('Each store monitors 20 products for seven days: 140 scheduled product-days per store-week. A stockout product-day records one monitored product unavailable on one day. The primary outcome is the count divided by 140, expressed as a percentage. The service target is 10%.')+formula('Stockout rate (%) = stockout product-days ÷ 140 × 100')+p('The accounting scenario charges 6 CU per stockout product-day. Alerts cost 12 CU in service fees and 8 CU in extra holding cost per store-week. These are explicit business assumptions for the spending calculation; they are not a measure of recovered sales.')+formula('Weekly accounting cost = 6 × stockout product-days + 20 when alerts are offered')),
        ('timeline','Learn from distinct studies inside one business',timeline+p('Every store has the same ID throughout the course. The three intervention cohorts are disjoint; a random offer in the pilot is never treated as voluntary adoption or as the selected later rollout. The forecast uses only the pre-policy period.')),
        ('route','Use one set of teaching materials',p('Start with the decision brief. Read the rows, follow the calculation, interpret the output, and make the call. Each lesson ends with a memo update that carries into the next lesson. The main lessons retain the conceptual breadth and worked operations of the original course through the continuing retail case.','Choose Present lesson to teach directly from the page. Arrow keys move through the material; Notes displays the explanation for a teaching block; Read this section returns to that exact place in the reading view. The same button is available in the technical continuations.','When you want to inspect a specification or reproduce a calculation, follow the technical link beside that calculation. The continuation shows the same analysis with executable code and a topic map to the supplied original slides. Existing guided-page bookmarks lead to the same complete lesson.')),
        ('deliverable','Your final deliverable',p('Prepare a recommendation that identifies the stores covered, the expected service improvement, its uncertainty, the cost rule, and the next operating action. Use the three intervention studies as evidence about their own populations. Explain how you would learn during the next phase of expansion.')+'<p><a href="lesson-1.html">Begin with the data →</a></p>')])
    write('study-guide.html',shell('Meet the retail case',case,'study-guide.html'))
    inventory='<ul>'+''.join(f'<li><strong>Lesson {i}: {esc(title)}</strong><br><a href="assets/lesson{i}-lab.ipynb" download>Notebook</a> · <a href="assets/lesson{i}-lab.py" download>Standalone Python lab</a> · <a href="assets/lesson{i}-results.json">Results</a></li>' for i,(title,_,__) in enumerate(MAP,1))+'</ul>'
    files=[('stores.csv','One store per row; cohort, delivery time, location, and baseline profile'),('raw-baseline.csv','The initial export for weeks 1–8, including the defects repaired in Lesson 1'),('baseline-repairs.csv','The ledger records used to reconcile flagged keys'),('baseline.csv','Clean weeks 1–16 for baseline and forecasting work'),('shelf-audit.csv','The independent week-16 audit of 30 sampled stores'),('store-weeks.csv','All 32 weeks, including actual offers, active policy, and outcomes')]
    dictionary=table(['Field','Meaning and timing'],[
        ['store_id, week','Together identify one observation; the store is the assignment unit'],['cohort','Pilot, Voluntary, or Rollout; fixed and disjoint'],['lead_days, urban','Known store attributes before each study'],['exposure','140 scheduled product-days per week'],['stockout_days, stockout_rate','Count and percentage observed during the target week'],['demand_forecast, promotion_plan','Prepared before the target week starts'],['demand_index','Realized during the week; unavailable to its advance forecast'],['lag_rate','Previous week’s observed stockout rate'],['offer','Retrospective study assignment/adoption label; excluded from baseline forecasting'],['active','Whether the offer is operating in this week'],['operating_cost','6 CU per stockout product-day plus 20 CU when active']],'Shared data dictionary')
    resources=document('Work with the same data.','Every lesson is generated from one store history, with one seed and stable identifiers.',[
        ('present','Teach directly from the website',p('Open a lesson and choose Present lesson. Use the arrow keys or Previous and Next, the slide menu to jump to a topic, and Home or End to reach the first or last slide. Escape exits presentation mode. Notes shows the explanation beside the teaching block; it is visible on the same screen, not a private presenter display.','Full screen expands the presentation when the browser permits it. Print slides opens the browser print dialog for a landscape slide handout or PDF. Read this section returns to the current topic in the continuous lesson. Reading and presentation are two views of the same authored content.')+'<ul>'+''.join(f'<li><a href="lesson-{i}.html?present=1">Present Lesson {i}: {esc(title)}</a></li>' for i,(title,_,__) in enumerate(MAP,1))+'</ul>'),
        ('data','Download the shared records','<ul>'+''.join(f'<li><a href="assets/{name}" download>{name}</a> — {esc(desc)}</li>' for name,desc in files)+'</ul>'+p('The complete store-week file is a retrospective record. Use the release and input timing specified in each lesson; the baseline download excludes the future offer and active-policy labels.')),
        ('dictionary','Read the fields before fitting a model',dictionary),
        ('labs','Run the lesson calculations',p('Each standalone Python lab includes the shared generator and its lesson’s worked calculation. Each notebook contains the same source in a shared setup cell, followed by the worked steps and saved output. Run all cells from the beginning; no data download or network call is needed by the lab.')+inventory),
        ('source','Inspect the model and release contract','<p><a href="assets/retail_case.py" download>Shared generator and analysis source</a> · <a href="assets/case-spec.json">Case specification and data fingerprint</a> · <a href="assets/course-results.json">All lesson results</a></p>'+p('The fingerprint identifies the same public store-week record across all ten result files. The source also retains the alternate policy outcomes used for known-answer comparisons.')),
        ('reproduce','Run a downloaded lab',p('Use Python 3.11 or later. Download the dependency list below and a standalone lesson lab into the same folder. Install the listed packages, then run the lab. It prints the lesson’s results after executing and checking the worked calculation.')+'<p><a href="assets/requirements.txt" download>Download requirements.txt</a></p><pre><code>python -m pip install -r requirements.txt\npython lesson1-lab.py</code></pre><p>To rebuild the complete website, use the instructions in the <a href="https://github.com/kochiuyu/data-to-decisions">course source repository</a>.</p><p><a href="python-bridge.html">Read the small Python bridge →</a></p>'),
        ('access','Reading and accessibility',p('All lessons, worked answers, and tables are available without an account. Charts include descriptive text and their values in tables. The course works without JavaScript; keyboard users can follow the roadmap and open the answer disclosures.'))])
    write('resources.html',shell('Shared data and labs',resources,'resources.html'))
    bridge=document('Read the code through the retail case.','Use a familiar observation to connect a calculation with its Python expression.',[
        ('readiness','Recognize the small pieces of Python',p('A list holds a sequence, a tuple can hold a fixed composite key, and a dictionary maps names to values. import makes a module available. Conditions select which operation to perform; loops repeat an operation. A list comprehension is a compact loop that creates a list.')+'<pre><code>columns = ["store_id", "week", "stockout_days"]\nkey = ("S001", 1)\nlabels = {"stockout_days": "Unavailable product-days"}\nweek_names = [f"week_{i:02d}" for i in range(1, 9)]\nfrom math import sqrt\nif len(week_names) == 8:\n    root_weeks = sqrt(len(week_names))</code></pre>'+p('A for loop is useful when the number of items is known; a while loop repeats while its condition remains true. File context managers such as with open(...) close files after use. pandas.read_csv handles a table import directly. You can focus on each calculation’s business meaning while learning this syntax.')),
        ('rows','A row has a business meaning',p('In the notebook, world() creates the shared records. The clean baseline has one row per store-week. The store_id and week columns form its key; exposure records the denominator.')+'<pre><code>w = world()\nclean = w["clean"]\nclean[["store_id", "week", "stockout_days", "exposure"]].head()</code></pre>'),
        ('rate','Calculate the same rate as Lesson 1','<pre><code>count = clean.stockout_days.sum()\nopportunities = clean.exposure.sum()\nrate = 100 * count / opportunities</code></pre>'+p(f'The result is {f(r[1]["rate"])}%. A dot selects a named column; sum() adds its values. Multiplying by 100 expresses the ratio as a percentage.')),
        ('groups','Change the unit deliberately','<pre><code>store_rates = (clean.assign(rate=100*clean.stockout_days/clean.exposure)\n    .groupby("store_id").rate.mean())</code></pre>'+p('groupby collects the repeated weeks for each store. mean calculates its baseline average. The result contains 150 store rates, which are the observations used in the descriptive and regression lessons.')),
        ('prediction','Follow a prediction and its residual','<pre><code>stores = w["stores"]\nX = np.column_stack([np.ones(len(stores)), stores.lead_days])\nbeta = np.linalg.lstsq(X, stores.baseline_rate, rcond=None)[0]\nprediction = X @ beta\nresidual = stores.baseline_rate - prediction</code></pre>'+p('The first column of X is an intercept. The second is delivery time. The @ operator multiplies the rows by the fitted coefficients. The residual subtracts the prediction from the actual baseline rate.')),
        ('next','Use the notebook as an audit trail',p('Run the shared setup first, then the lesson’s worked cell. Read its assertion as a check that the reconstructed result matches the displayed lesson. Change one input or analytical choice and explain the effect before trying another.')+'<p><a href="resources.html#labs">Choose a lesson lab →</a></p>')])
    write('python-bridge.html',shell('Python through the running case',bridge,'python-bridge.html'))
    evidence=table(['Study and target','Estimated reduction (points)','95% interval','Accounting saving (CU/store-week)'],[
        ['Randomized pilot: 50 eligible pilot stores',f(r[7]['effect']['value']),f(r[7]['effect']['low'])+' to '+f(r[7]['effect']['high']),f(r[7]['savings']['value'])],
        ['Voluntary cohort: adjusted all-store target',f(r[9]['estimate']),f(r[9]['low'])+' to '+f(r[9]['high']),'Model implication: '+f(8.4*r[9]['estimate']-20)],
        ['Later rollout: selected adopter stores',f(r[10]['effect']['value']),f(r[10]['effect']['low'])+' to '+f(r[10]['effect']['high']),f(r[10]['savings']['value'])]],'Three studies of the same policy, with named targets')
    synthesis=document('Recommend the next phase of expansion.','Use the evidence accumulated through the ten lessons to advise the operations director.',[
        ('decision','The recommendation',p('Continue a measured expansion of replenishment alerts in stores comparable to the later rollout group. Use the forecast to organize the weekly review workload, retain a comparison during expansion, and track both stockout rates and the cost of delivering the service.','The operational case is a persistent stockout burden above the 10% target. The intervention studies point to improved availability, while their economic results depend on the target store mix and the stated accounting costs. The pilot’s saving interval reaches slightly below zero, so a staged commitment remains useful.')),
        ('baseline','What established the need for action',p(f'Lesson 1 reconciled {r[1]["clean"]:,} store-weeks and established a baseline rate of {f(r[1]["rate"])}%. Lesson 2 showed how that burden differed across delivery groups. The independent week-16 audit estimated {f(r[3]["mean"])}%, with interval {f(r[3]["low"])}%–{f(r[3]["high"])}%.','These are complementary observations of the same business at named times. They justify attention to replenishment and preserve a stable definition for measuring progress.')),
        ('operations','How the analysis supports daily work',p(f'Lessons 4 and 5 made the relationship between store conditions and stockout pressure explicit. Lesson 6 selected {r[6]["selected"]} using later validation weeks and recorded final forecast error of {f(r[6]["rmse"])} points, versus {f(r[6]["baseline_rmse"])} for the mean-rate rule.','The review queue should be formed before the week starts. Record staff actions and effort so the company can distinguish a useful forecast from an effective operational response.')),
        ('impact','What the intervention evidence says',evidence+p('The randomized pilot estimates the offer’s effect for its pilot population. The adjusted voluntary result uses recorded starting conditions to represent all stores in that cohort. The time comparison evaluates the selected later adopters. Their store mixes differ, so they should not be averaged automatically into a universal effect.')),
        ('economics','Make the break-even point visible',formula(f'Break-even reduction = 20 ÷ 8.4 = {f(r[7]["cost_threshold"])} percentage points')+p(f'The pilot’s estimated weekly saving is {f(r[7]["savings"]["value"])} CU, with interval {f(r[7]["savings"]["low"])} to {f(r[7]["savings"]["high"])}. The later-rollout saving is {f(r[10]["savings"]["value"])} CU, with interval {f(r[10]["savings"]["low"])} to {f(r[10]["savings"]["high"])}.','These savings use the supplied 6 CU stockout charge and 20 CU policy cost. Before committing a budget, finance should agree whether that accounting rule represents the business objective and update it if service fees or carrying costs change.')),
        ('next-phase','Specify what the next phase will record',p('Name the eligible stores, offer date, common monitoring basket, and follow-up window before expansion. Preserve the weekly stockout denominator and identify which stores provide the comparison. Record the alert service actually delivered, review effort, inventory costs, and other operational changes.','Set the review date and decision rule in advance: continue where the service improvement and cost case support it; revise the operating protocol where implementation absorbs the gain. The next analysis should update this memo using the same store IDs and explicit targets.')),
        ('exercise','Write your own board paragraph',p('In one paragraph, name the target stores, the evidence you rely on, the expected improvement in business units, the cost rule, and the next action. Then explain which new result would change your recommendation.')+'<details><summary>Compare with a possible response</summary><div>'+p('Approve a staged next phase for stores resembling the selected rollout adopters. The time comparison estimates a meaningful reduction in stockouts with positive accounting savings under the supplied cost rule. Retain a contemporaneous comparison and audit delivery of the alert service. Use the pilot’s less precise financial result to avoid assuming the same payoff at every store. Review both availability and operating costs at the pre-specified decision date.')+'</div></details>')])
    write('synthesis.html',shell('The retail expansion recommendation',synthesis,'synthesis.html'))
